  /* ===================================================================
     1. CONFIG
     =================================================================== */
  var CONFIG = {
    title:   "Pawko",
    /* One sentence: the two beats of a round are a wave dropped on the board
       and a card played between two waves. The stage under it shows the first
       one — the finger taps, a ball rattles down the pegs. */
    tagline: "<b class=\"w-tap\">Tap</b> to drop a <b class=\"w-wave\">wave of balls</b>, play a <b class=\"w-card\">card</b> between waves",
    /* NO CLOCK. A round is five waves: it ends when the last ball of the fifth
       has found a gate, however long that takes. */
    gameSeconds: 0,
    storeUrl: {
      ios:     "https://newrare.app/#playables",
      android: "https://newrare.app/#playables",
      fallback:"https://newrare.app/#playables"
    },
    designWidth: 720, designHeight: 1280, bg: "#2a0a14",
    layout: { hudHeight: 150, ctaHeight: 112, sideMargin: 30 },
    intro: { logo: null, demo: "tap", caption: "" },
    keyboard: true,
    hud: { score: true, timer: false },
    /* THE BED. One track, six windows of it: five for the bands of the climb
       (below) and a quiet, slower one under the menus. The entry points are
       the track's own seams, measured (docs/MUSIC.md): the body starts at
       10 s, breaks at 45-55, 95-110 and 130-135, and the music ends at 176. */
    music: {
      volume: 0.11, fade: 1.8,
      menu: { from: 0, length: 36, rate: 0.85, gain: 0.5 }
    },
    /* THE FIVE BANDS OF THE CLIMB, six levels apiece — the same stretches the
       level map names on its card. Each carries the PICTURE the round and the
       end screen are played over and the STRETCH of the track under it, so the
       two can only turn over together. `scene` is a key of CONFIG.art, injected
       out of assets/image/embed/pawko-background-phone-NN.webp. A playable is
       one round at level 0: it rides the first band, the only scene and the
       only window the builder embeds in it. */
    bands: [
      { scene: "backgroundPhone01", music: { from: 10,  length: 35 } },  //  1-6   Warm-up
      { scene: "backgroundPhone02", music: { from: 55,  length: 40 } },  //  7-12  Pressure
      { scene: "backgroundPhone03", music: { from: 105, length: 25 } },  // 13-18  Squeeze
      { scene: "backgroundPhone04", music: { from: 135, length: 21 } },  // 19-24  Overdrive
      { scene: "backgroundPhone05", music: { from: 155, length: 21 } }   // 25-30  Meltdown
    ],
    copy: {
      start:      "Tap to play",
      ctaBar:     "Install now",
      ctaEnd:     "Play the full game",
      replay:     "Replay the demo",
      scoreLabel: "Score",
      timeLabel:  "Time",
      endScore:   "Final score",
      gameOver:   "Round over",
      timeUp:     "Time's up!",
      jackpot:    "Jackpot!",
      waveLabel:  "Wave",
      ballsLabel: "Balls"
    },

    /* --- game tunables ------------------------------------------------
       The level layer lerps the ones its manifest names (web.levels.tune)
       between level 1 and level 30, in place. */
    play: {
      waves: 5,          // waves of balls in a round; one card is played before each
      balls: 10,         // balls in a wave
      specials: 8,       // special pegs already on the board when the round opens
      malusGates: 0,     // how many of the two edge gates take points away (0-2)
      pegValue: 10,      // what a classic peg pays; every other peg is a multiple of it
      gate: { edge: 50, mid: 150, jackpot: 500, malus: -100 },
      goal: 16000,       // the playable's own objective: 1 star at it, 2 at 1.5x, 3 at 2.2x
      cornerClear: 96,   // the gate band stops this far above the frame's foot, so the
                         // web target's two corner pills never cover a gate's value
      ballHits: 60       // a ball that has bounced this often burns out (a loop never ends)
    },
    physics: {
      gravity: 1300,     // design px / s^2
      peg: 0.45,         // restitution off a classic peg
      bumper: 1.05,      // ...off a bumper, which also throws the ball back at bumperKick
      bumperKick: 760,   // minimum exit speed off a bumper
      wall: 0.65,
      maxSpeed: 1600,
      step: 1 / 240      // fixed physics step; the frame is cut into as many as it needs
    }
  };

  /* ===================================================================
     2. ASSETS
     =================================================================== */
  var ASSETS = {
    /* No `logo`: this game ships a painted logotype
       (assets/image/master/pawko-title.png) and the shell hides #app-icon as
       soon as one exists. The balls, the card pictograms and the decor pool
       are painted too — cut out of pawko-object-other.png and named in
       art.objects of the manifest (ball01-05, icon01-08, decor-01..04). */
    images: {},
    sounds: {
      // The background bed, looped and crossfaded by Music. The playable's cut
      // is the FIRST band's window and nothing else; the web target ships the
      // whole track instead (`web.music` in the manifest):
      //   ffmpeg -ss 10 -t 35 -i assets/audio/music/pawko.mp3 -ac 1 -ar 44100 -b:a 64k music.mp3
      // assets/audio/sfx/*.{mp3,ogg}, trimmed and re-encoded mono 32 kHz / 64 kbps
      // hit:   impact-metal-light-05                               (a ball on a classic peg, pitched by the ball's heat)
      // bump:  impact-plate-heavy-02                   (a bumper throws the ball back)
      // fire:  whoosh-whistle-ascending-02 (a ball catches fire)
      // ice:   impact-glass-light-01                   (a ball freezes)
      // zap:   powerup-05                (a magnet peg charges the ball)
      // boom:  explosion-crunch-01                        (a bomb goes off)
      // gate:  bell-ping-cute-01                 (a ball lands in a bonus gate)
      // bad:   error-ui-03                       (a malus gate, a tap with no card)
      // card:  card-place-02                                                 (a card is played)
      // drop:  chip-handle-04                                      (a wave leaves the chute)
      // goal:  jingle-pizzicato-05       (the objective is reached)
      // out:   pop-close-01                    (a ball burns out)
      hit: "data:audio/mpeg;base64,",
      bump: "data:audio/mpeg;base64,",
      fire: "data:audio/mpeg;base64,",
      ice: "data:audio/mpeg;base64,",
      zap: "data:audio/mpeg;base64,",
      boom: "data:audio/mpeg;base64,",
      gate: "data:audio/mpeg;base64,",
      bad: "data:audio/mpeg;base64,",
      card: "data:audio/mpeg;base64,",
      drop: "data:audio/mpeg;base64,",
      goal: "data:audio/mpeg;base64,",
      out: "data:audio/mpeg;base64,",
      music: "data:audio/mpeg;base64,",
      // End-screen cues, shared by every game (played through Sound.cue, so a
      // game that drops them falls back to the synthesized beeps).
      // uiScore: chime-ping-correct-01
      // uiStar:  mallet-chime-ring-02  (pitched per star)
      // uiRow:   beep-select-01
      uiScore: "data:audio/mpeg;base64,",
      uiStar: "data:audio/mpeg;base64,",
      uiRow: "data:audio/mpeg;base64,"
    }
  };

  /* ===================================================================
     6. GAME — PAWKO
     A pachinko board of pegs under a chute. A round is FIVE WAVES of balls:
     before each one the player plays ONE of the five cards dealt at the top of
     the board — a card turns pegs into fire, ice, bumpers, magnets or bombs,
     doubles the classic pegs or the gates, or fattens the waves — and a card
     played is gone, so the ORDER is the strategy. Then a tap on the board picks
     where the wave falls from. Every peg a ball touches pays, a ball on fire or
     frozen pays more, a charged one pays double, and the gate a ball ends in
     adds (or takes) a bonus. The objective gauge fills the board behind the
     pegs; the round ends with the last ball of the last wave.
     =================================================================== */
  var Game = (function () {
    var P = CONFIG.play, PH = CONFIG.physics;

    /* --- geometry (design px), rebuilt by geometry() ------------------- */
    var BL, BR, BW;                 // the board's left / right edge and width
    var DECK_Y, DECK_H = 150;       // the card deck, under the HUD
    var BOARD_TOP;                  // the pinboard begins here (balls spawn just under it)
    var GATE_TOP, GATE_BOTTOM, GATE_H = 84;
    var ROW0_Y, ROWS, PITCH_X = 66, PITCH_Y = 60;
    var PEG_R = 11, BUMPER_R = 13, BALL_R = 12;
    var CARD_W = 118, CARD_H = 150, CARD_GAP = 12;

    /* --- the peg types --------------------------------------------------
       `mul` is what a hit pays, in classic pegs (CONFIG.play.pegValue): the
       level layer raises the peg value along the climb, so every number on
       the board — and the objective with it — grows with the level. */
    var TYPES = {
      classic: { mul: 1,  color: "#ffcf5a", r: PEG_R },
      bumper:  { mul: 3,  color: "#ff4d6d", r: BUMPER_R },
      fire:    { mul: 2,  color: "#ff7a1a", r: PEG_R },
      ice:     { mul: 2,  color: "#5ad8ff", r: PEG_R },
      magnet:  { mul: 2,  color: "#c46bff", r: PEG_R },
      bomb:    { mul: 25, color: "#3a3a4a", r: PEG_R }
    };
    /* the three heats a ball can carry: how long, and what they add to a hit
       (in classic pegs — a burning ball pays half a peg more, a frozen one a
       whole peg more, a charged one pays double) */
    var BURN_S = 3, FROZEN_S = 2, CHARGED_S = 3, BURN_ADD = 0.5, FROZEN_ADD = 1;
    var MAGNET_REACH = 110, MAGNET_PULL = 320;   // a magnet peg pulls balls this far, this hard
    var BLAST_REACH = 130, BLAST_SPEED = 900;    // a bomb throws every ball inside its reach

    /* --- the cards ------------------------------------------------------
       `icon` is a painted cut of the object sheet (CONFIG.art.iconNN, adopted
       in the manifest); `n` is how many pegs the card turns, or how many balls
       it adds. The name and the description are what the player reads — the
       desk translates them.

       TWO KINDS, and the difference is the whole strategy. A card that TURNS
       PEGS is permanent: the board keeps its fire, its bumpers and its bombs
       for the rest of the round. A card that MULTIPLIES — double pegs, double
       gates, a fatter wave — lasts ONE wave, the one it is played before. So
       the pegs are turned first and the multipliers are spent on the board
       they built, and a player who opens with Double has paid it on a board
       of plain brass. */
    var CARDS = {
      double: { icon: "icon01", name: "Double", desc: "Classic pegs pay double this wave",   n: 0,  color: "#ffd166", wave: true },
      fire:   { icon: "icon02", name: "Fire",   desc: "5 pegs catch fire",                   n: 5,  color: "#ff7a1a" },
      ice:    { icon: "icon03", name: "Ice",    desc: "5 pegs turn to ice",                  n: 5,  color: "#5ad8ff" },
      bumper: { icon: "icon04", name: "Bumper", desc: "10 pegs become bumpers",              n: 10, color: "#ff4d6d" },
      magnet: { icon: "icon05", name: "Magnet", desc: "4 pegs turn magnetic",                n: 4,  color: "#c46bff" },
      bomb:   { icon: "icon06", name: "Bomb",   desc: "3 pegs become bombs",                 n: 3,  color: "#9aa0b4" },
      balls:  { icon: "icon07", name: "Balls",  desc: "6 more balls in this wave",           n: 6,  color: "#ff5c5c", wave: true },
      gold:   { icon: "icon08", name: "Gold",   desc: "Gates pay double this wave, no malus", n: 0,  color: "#ffb830", wave: true }
    };
    var CARD_KEYS = ["double", "fire", "ice", "bumper", "magnet", "bomb", "balls", "gold"];

    /* --- state ------------------------------------------------------------ */
    var pegs, rows, balls, spawnQ, gates, deck;
    var state, stateT, wave, score, hits, gateScore, waveScore, bestWave;
    var ended, tapX, levelD, target, goalHit, BAND;
    var boost, deckShake, ballId, burnt;   // boost: the one-wave cards in force
    var sprites, bgCanvas, bgHasScene, acc, sfxT, tAnim;
    var seed;

    /* --- the level ------------------------------------------------------ */
    /* The web target's level layer hands `d` (0 at the foot of the climb, 1 at
       the top) before the round starts, and null for an endless run. The
       objective is the same number the map writes on its card — one lerp over
       web.levels.objective — so the gauge behind the pegs and the pill in the
       corner can never disagree. A playable never gets the call and plays to
       its own goal. */
    function applyLevel(d) { levelD = (d == null) ? null : d; }
    function goalOf() {
      var L = CONFIG.web && CONFIG.web.levels && CONFIG.web.levels.objective;
      if (levelD == null || !L) return P.goal;
      var step = L.step || 1, v = L.from + (L.to - L.from) * levelD;
      return Math.round(v / step) * step;
    }
    function bandFor() {
      var b = CONFIG.bands;
      if (!CONFIG.level) return b[0];
      return b[clamp(Math.floor((CONFIG.level - 1) / 6), 0, b.length - 1)];
    }

    /* A tiny LCG for what has to be the same every time a level is opened:
       the five cards dealt. The deck is the puzzle of a level, so it is seeded
       by the level number; the playable and the endless run draw from Rand. */
    function lcg() {
      seed = (seed * 1664525 + 1013904223) >>> 0;
      return seed / 4294967296;
    }
    function draw() { return CONFIG.level ? lcg() : Math.random(); }

    /* --- helpers ---------------------------------------------------------- */
    function font(size, weight) {
      return (weight || 900) + " " + Math.round(size) + "px -apple-system,Segoe UI,Roboto,sans-serif";
    }
    function roundRect(g, x, y, w, h, r) {
      g.beginPath();
      g.moveTo(x + r, y);
      g.arcTo(x + w, y, x + w, y + h, r);
      g.arcTo(x + w, y + h, x, y + h, r);
      g.arcTo(x, y + h, x, y, r);
      g.arcTo(x, y, x + w, y, r);
      g.closePath();
    }
    function makeCanvas(w, h) {
      var c = document.createElement("canvas");
      c.width = Math.ceil(w * view.dpr); c.height = Math.ceil(h * view.dpr);
      c.getContext("2d").scale(view.dpr, view.dpr);
      return c;
    }
    function shuffle(a) {
      for (var i = a.length - 1; i > 0; i--) {
        var j = Math.floor(draw() * (i + 1)), t = a[i]; a[i] = a[j]; a[j] = t;
      }
      return a;
    }

    /* --- geometry --------------------------------------------------------- */
    function geometry() {
      BL = Layout.left; BR = Layout.right; BW = BR - BL;
      DECK_Y = Layout.top + 8;
      BOARD_TOP = DECK_Y + DECK_H + 12;
      /* The gate band stops short of the frame's foot on every target: the
         web build's corner pills (the level's stars, MENU / OPTIONS) sit in the
         last ~70 px and a gate's value is a word a player reads. */
      GATE_BOTTOM = Math.min(Layout.bottom, CONFIG.designHeight - P.cornerClear);
      GATE_TOP = GATE_BOTTOM - GATE_H;
      ROW0_Y = BOARD_TOP + 56;
      ROWS = Math.max(6, Math.floor((GATE_TOP - 64 - ROW0_Y) / PITCH_Y) + 1);
    }

    /* The board: staggered rows, ten pegs on an even row, nine on an odd one,
       every peg a classic one until the specials and the cards say otherwise. */
    function buildPegs() {
      pegs = []; rows = [];
      for (var r = 0; r < ROWS; r++) {
        var odd = r % 2, n = odd ? 9 : 10, x0 = BL + PITCH_X / 2 + (odd ? PITCH_X / 2 : 0);
        var row = [];
        for (var c = 0; c < n; c++) {
          var peg = { x: x0 + c * PITCH_X, y: ROW0_Y + r * PITCH_Y, type: "classic", r: PEG_R,
                      flash: 0, spent: false, row: r, id: pegs.length };
          pegs.push(peg); row.push(peg);
        }
        rows.push(row);
      }
    }
    function placePegs() {   // after a resize: same pegs, new positions
      for (var r = 0; r < rows.length; r++) {
        var odd = r % 2, x0 = BL + PITCH_X / 2 + (odd ? PITCH_X / 2 : 0);
        for (var c = 0; c < rows[r].length; c++) {
          rows[r][c].x = x0 + c * PITCH_X; rows[r][c].y = ROW0_Y + r * PITCH_Y;
        }
      }
    }
    function setType(peg, type) {
      peg.type = type; peg.r = TYPES[type].r; peg.spent = false; peg.flash = 1;
    }
    function classicPegs(skipTopRow) {
      var out = [];
      for (var i = 0; i < pegs.length; i++)
        if (pegs[i].type === "classic" && !(skipTopRow && pegs[i].row === 0)) out.push(pegs[i]);
      return out;
    }
    /* Turn `n` random classic pegs into `type`. Returns the pegs touched. */
    function convert(n, type) {
      var pool = shuffle(classicPegs(true)), out = [];
      for (var i = 0; i < n && i < pool.length; i++) { setType(pool[i], type); out.push(pool[i]); }
      return out;
    }

    /* The gates: five cells along the foot of the board — a jackpot in the
       middle, narrow, two mid gates beside it, two wide edge gates. A level
       may turn one or both edges into a malus. */
    function buildGates() {
      var vals, frac = [0.24, 0.20, 0.12, 0.20, 0.24];
      if (gates) {                     // a resize mid-round: same values, new cells
        vals = [];
        for (var k = 0; k < 5; k++) vals.push(gates[k].val);
      } else {
        vals = [P.gate.edge, P.gate.mid, P.gate.jackpot, P.gate.mid, P.gate.edge];
        var malus = P.malusGates | 0;
        if (malus >= 1) vals[draw() < 0.5 ? 0 : 4] = P.gate.malus;
        if (malus >= 2) { vals[0] = P.gate.malus; vals[4] = P.gate.malus; }
      }
      gates = []; var x = BL;
      for (var i = 0; i < 5; i++) {
        var w = BW * frac[i];
        gates.push({ x: x, w: w, cx: x + w / 2, val: vals[i], base: vals[i], flash: 0, jackpot: i === 2 });
        x += w;
      }
    }
    function gateValue(g) {
      var v = g.val;
      if (boost.gold) { if (v < 0) v = P.gate.edge; v *= 2; }
      return v;
    }

    /* The deck: five of the eight cards, no doubles, dealt for the level. */
    function buildDeck() {
      var keys = shuffle(CARD_KEYS.slice()).slice(0, 5);
      deck = [];
      for (var i = 0; i < 5; i++) deck.push({ key: keys[i], used: false, pop: 0 });
    }
    function cardX(i) {
      var total = 5 * CARD_W + 4 * CARD_GAP;
      return (view.w - total) / 2 + i * (CARD_W + CARD_GAP);
    }
    function cardAt(p) {
      if (p.y < DECK_Y - 10 || p.y > DECK_Y + CARD_H + 10) return -1;
      for (var i = 0; i < 5; i++) {
        var x = cardX(i);
        if (p.x >= x - 6 && p.x <= x + CARD_W + 6) return i;
      }
      return -1;
    }

    /* --- lifecycle -------------------------------------------------------- */
    function reset() {
      BAND = bandFor();
      Art.backdrop(BAND.scene);
      seed = ((CONFIG.level | 0) * 7919 + 12345) >>> 0;
      geometry();
      buildSprites();
      bgCanvas = null; buildBackground();
      buildPegs();
      gates = null; buildGates();
      buildDeck();
      balls = []; spawnQ = []; ballId = 0; burnt = 0;
      score = 0; hits = 0; gateScore = 0; waveScore = 0; bestWave = 0;
      wave = 0; boost = { double: false, gold: false, extra: 0 };
      ended = false; goalHit = false; deckShake = 0; acc = 0; sfxT = 0; tAnim = 0;
      tapX = view.w / 2;
      target = goalOf();
      // the board opens with a few specials already on it, never a bomb
      var kinds = ["bumper", "fire", "ice", "magnet"];
      for (var i = 0; i < (P.specials | 0); i++) convert(1, kinds[i % kinds.length]);
      for (var j = 0; j < pegs.length; j++) pegs[j].flash = 0;
      setState("choose");
      HUD.setScoreNow(0);
      HUD.setLeft("1/" + P.waves, CONFIG.copy.waveLabel);
      HUD.setRight(ballsInWave(), CONFIG.copy.ballsLabel);
      Music.play(CONFIG.level ? BAND.music : null);
    }
    /* The motor lays the frame out before any round exists (the intro, a turn
       of the device on the menu): nothing to move then — reset() builds the
       board from Layout when the round starts. */
    function onResize() {
      if (!rows) return;
      geometry();
      placePegs();
      buildGates();
      buildSprites();
      bgCanvas = null; buildBackground();
    }
    function setState(s) { state = s; stateT = 0; }
    function ballsInWave() { return (P.balls | 0) + boost.extra; }
    function classicPts() { return P.pegValue * (boost.double ? 2 : 1); }

    /* --- input -------------------------------------------------------------- */
    function clampX(x) { return clamp(x, BL + 40, BR - 40); }
    function onDown(p) {
      if (ended) return;
      if (state === "choose") {
        var i = cardAt(p);
        if (i >= 0 && !deck[i].used) { playCard(i); return; }
        if (p.y > BOARD_TOP) {
          deckShake = 0.45;
          Notify.say("Pick a card", { kind: "info" });
          Sound.clip("bad", 0.25, 1.4);
        }
        return;
      }
      if (state === "aim" && p.y > BOARD_TOP) { tapX = clampX(p.x); dropWave(); }
    }
    function onMove(p) { if (state === "aim") tapX = clampX(p.x); }

    /* --- the cards ------------------------------------------------------- */
    function playCard(i) {
      var card = deck[i], def = CARDS[card.key], touched = [];
      card.used = true; card.pop = 1;
      switch (card.key) {
        case "double": boost.double = true; for (var q = 0; q < pegs.length; q++) if (pegs[q].type === "classic") pegs[q].flash = 0.6; break;
        case "gold":   boost.gold = true; for (var g = 0; g < 5; g++) gates[g].flash = 1; break;
        case "balls":  boost.extra += def.n; HUD.setRight(ballsInWave(), CONFIG.copy.ballsLabel); break;
        default:       touched = convert(def.n, card.key);
      }
      for (var k = 0; k < touched.length; k++) {
        Fx.burst(touched[k].x, touched[k].y, { color: [def.color, "#ffffff"], count: 10, speed: 220, life: .5, grav: 200, size: 4 });
      }
      Fx.ring(cardX(i) + CARD_W / 2, DECK_Y + CARD_H / 2, { from: 30, to: 160, color: def.color, width: 6, life: .45 });
      Pop.show("manifest", { word: def.name, sub: def.desc, hold: 900 });
      Sound.clip("card", 0.6, 1);
      setState("aim");
    }

    /* --- the waves --------------------------------------------------------- */
    function dropWave() {
      wave++;
      waveScore = 0;
      var n = ballsInWave();
      for (var i = 0; i < n; i++) spawnQ.push({ at: i * 0.11, x: tapX });
      // a spent bomb comes back armed with every wave
      for (var j = 0; j < pegs.length; j++) if (pegs[j].type === "bomb") pegs[j].spent = false;
      HUD.setLeft(wave + "/" + P.waves, CONFIG.copy.waveLabel);
      HUD.setRight(n, CONFIG.copy.ballsLabel);
      Pop.show("ribbon", { word: Lang.t("Wave") + " " + wave + "/" + P.waves, hold: 500 });
      Sound.clip("drop", 0.55, 1);
      setState("drop");
    }
    function spawnBall(x) {
      balls.push({
        id: ballId++,
        x: x + Rand.range(-14, 14), y: BOARD_TOP + BALL_R + 2,
        vx: Rand.range(-60, 60), vy: 80,
        burn: 0, frozen: 0, charged: 0,
        hits: 0, still: 0, touch: {}, trail: 0
      });
    }
    function endWave() {
      if (waveScore > bestWave) bestWave = waveScore;
      boost = { double: false, gold: false, extra: 0 };   // the one-wave cards are spent
      if (wave >= P.waves) { setState("finish"); return; }
      setState("between");
    }
    function nextWave() {
      HUD.setLeft((wave + 1) + "/" + P.waves, CONFIG.copy.waveLabel);
      HUD.setRight(ballsInWave(), CONFIG.copy.ballsLabel);
      setState("choose");
    }

    /* --- the simulation ---------------------------------------------------- */
    function update(dt) {
      tAnim += dt;
      stateT += dt;
      if (deckShake > 0) deckShake -= dt;
      var i;
      for (i = 0; i < pegs.length; i++) if (pegs[i].flash > 0) pegs[i].flash = Math.max(0, pegs[i].flash - dt * 4);
      for (i = 0; i < 5; i++) {
        if (gates[i].flash > 0) gates[i].flash = Math.max(0, gates[i].flash - dt * 2.5);
        if (deck[i].pop > 0) deck[i].pop = Math.max(0, deck[i].pop - dt * 3);
      }
      if (ended) return;
      if (state === "drop") {
        // the chute lets the wave go one ball at a time
        for (i = 0; i < spawnQ.length; i++) spawnQ[i].at -= dt;
        while (spawnQ.length && spawnQ[0].at <= 0) spawnBall(spawnQ.shift().x);
        acc += dt;
        var n = 0;
        while (acc >= PH.step && n < 12) { substep(PH.step); acc -= PH.step; n++; }
        if (n === 12) acc = 0;
        if (!spawnQ.length && !balls.length) endWave();
      } else if (state === "between") {
        if (stateT > 0.7) nextWave();
      } else if (state === "finish") {
        if (stateT > 0.9) endRun(CONFIG.copy.gameOver);
      }
    }

    function substep(h) {
      var i, j, b, p;
      for (i = balls.length - 1; i >= 0; i--) {
        b = balls[i];
        // the heats wear off
        if (b.burn > 0) b.burn -= h;
        if (b.frozen > 0) b.frozen -= h;
        if (b.charged > 0) b.charged -= h;
        // gravity, halved for a frozen ball
        b.vy += PH.gravity * h * (b.frozen > 0 ? 0.5 : 1);
        // magnet pegs pull
        pullMagnets(b, h);
        // a charged ball pulls the others
        if (b.charged > 0) {
          for (j = 0; j < balls.length; j++) {
            var o = balls[j]; if (o === b) continue;
            var dx = b.x - o.x, dy = b.y - o.y, d = Math.sqrt(dx * dx + dy * dy);
            if (d > 0 && d < MAGNET_REACH) {
              var s = (1 - d / MAGNET_REACH) * MAGNET_PULL * h;
              o.vx += dx / d * s; o.vy += dy / d * s;
            }
          }
        }
        var sp = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
        if (sp > PH.maxSpeed) { b.vx *= PH.maxSpeed / sp; b.vy *= PH.maxSpeed / sp; }
        var sm = b.frozen > 0 ? 0.55 : 1;
        b.x += b.vx * h * sm; b.y += b.vy * h * sm;
        // walls
        if (b.x - BALL_R < BL) { b.x = BL + BALL_R; b.vx = Math.abs(b.vx) * PH.wall; }
        if (b.x + BALL_R > BR) { b.x = BR - BALL_R; b.vx = -Math.abs(b.vx) * PH.wall; }
        if (b.y - BALL_R < BOARD_TOP - 40) { b.y = BOARD_TOP - 40 + BALL_R; b.vy = Math.abs(b.vy) * PH.wall; }
        // pegs
        collidePegs(b);
        // the gate band
        if (b.y > GATE_TOP + BALL_R) { collect(b); balls.splice(i, 1); continue; }
        // a ball that stopped moving, or that will never stop bouncing
        var v2 = b.vx * b.vx + b.vy * b.vy;
        b.still = v2 < 400 ? b.still + h : 0;
        if (b.still > 1.2) { b.vx = Rand.range(-160, 160); b.vy = -220; b.still = 0; }
        if (b.hits >= P.ballHits) { burnOut(b); balls.splice(i, 1); continue; }
      }
      // ball on ball: equal masses, elastic
      for (i = 0; i < balls.length; i++) {
        for (j = i + 1; j < balls.length; j++) {
          var a = balls[i], c = balls[j];
          var ex = c.x - a.x, ey = c.y - a.y, d2 = ex * ex + ey * ey, rr = BALL_R * 2;
          if (d2 >= rr * rr || d2 === 0) continue;
          var dist = Math.sqrt(d2), nx = ex / dist, ny = ey / dist, depth = rr - dist;
          a.x -= nx * depth / 2; a.y -= ny * depth / 2;
          c.x += nx * depth / 2; c.y += ny * depth / 2;
          var rel = (a.vx - c.vx) * nx + (a.vy - c.vy) * ny;
          if (rel <= 0) continue;
          a.vx -= rel * nx; a.vy -= rel * ny;
          c.vx += rel * nx; c.vy += rel * ny;
        }
      }
    }

    function pullMagnets(b, h) {
      var r0 = Math.floor((b.y - ROW0_Y) / PITCH_Y);
      for (var r = Math.max(0, r0 - 2); r <= Math.min(rows.length - 1, r0 + 2); r++) {
        var row = rows[r];
        for (var c = 0; c < row.length; c++) {
          var p = row[c];
          if (p.type !== "magnet") continue;
          var dx = p.x - b.x, dy = p.y - b.y, d = Math.sqrt(dx * dx + dy * dy);
          if (d < MAGNET_REACH && d > 0) {
            var s = (1 - d / MAGNET_REACH) * MAGNET_PULL * h;
            b.vx += dx / d * s; b.vy += dy / d * s;
          }
        }
      }
    }

    /* Circle against circle, the ball pushed out by the whole overlap and its
       velocity reflected off the normal — a peg never moves. One hit per
       CONTACT: the peg is remembered while the two overlap and forgotten the
       moment they part, so a ball resting on a peg does not score every step. */
    function collidePegs(b) {
      var r0 = Math.floor((b.y - ROW0_Y) / PITCH_Y);
      for (var r = Math.max(0, r0 - 1); r <= Math.min(rows.length - 1, r0 + 1); r++) {
        var row = rows[r];
        for (var c = 0; c < row.length; c++) {
          var p = row[c];
          var dx = b.x - p.x, dy = b.y - p.y, rr = BALL_R + p.r, d2 = dx * dx + dy * dy;
          if (d2 >= rr * rr) { if (b.touch[p.id]) delete b.touch[p.id]; continue; }
          var d = Math.sqrt(d2) || 1e-6, nx = dx / d, ny = dy / d, depth = rr - d;
          b.x += nx * depth; b.y += ny * depth;
          var dot = b.vx * nx + b.vy * ny;
          var e = p.type === "bumper" ? PH.bumper : PH.peg;
          if (dot < 0) { b.vx -= (1 + e) * dot * nx; b.vy -= (1 + e) * dot * ny; }
          if (p.type === "bumper") {
            var sp = Math.sqrt(b.vx * b.vx + b.vy * b.vy);
            if (sp < PH.bumperKick) { var k = PH.bumperKick / Math.max(sp, 1); b.vx *= k; b.vy *= k; }
          }
          if (!b.touch[p.id]) { b.touch[p.id] = true; hit(p, b); }
        }
      }
      // anything remembered from two rows away is long out of contact
      for (var id in b.touch) if (Math.abs(pegs[id].y - b.y) > PITCH_Y * 2) delete b.touch[id];
    }

    /* --- a hit --------------------------------------------------------------- */
    function hit(p, b) {
      b.hits++; hits++;
      var T = TYPES[p.type], base = T.mul * P.pegValue, color = T.color, tier = 0, snd = "hit", rate = 1;
      if (p.type === "classic") base = classicPts();
      if (p.type === "bomb") {
        if (p.spent) { base = classicPts(); color = TYPES.classic.color; }
        else { blast(p); tier = 3; }
      }
      // the heats: a frozen ball catches no fire, a burning one does not freeze
      if (p.type === "fire") {
        if (b.frozen > 0) { b.frozen = 0; } else { b.burn = BURN_S; }
        snd = "fire"; rate = Rand.range(0.95, 1.1);
      } else if (p.type === "ice") {
        if (b.burn > 0) { b.burn = 0; } else { b.frozen = FROZEN_S; }
        snd = "ice"; rate = Rand.range(1.0, 1.2);
      } else if (p.type === "magnet") {
        b.charged = CHARGED_S; snd = "zap"; rate = Rand.range(0.9, 1.1);
      } else if (p.type === "bumper") {
        snd = "bump"; rate = Rand.range(0.9, 1.15);
      } else if (p.type === "bomb" && tier === 3) {
        snd = "boom"; rate = 1;
      } else {
        rate = (b.burn > 0 ? 1.25 : b.frozen > 0 ? 0.8 : 1) + Rand.range(-0.05, 0.05);
      }
      var add = ((b.burn > 0 ? BURN_ADD : 0) + (b.frozen > 0 ? FROZEN_ADD : 0)) * P.pegValue;
      var m = b.charged > 0 ? 2 : 1;
      var pts = Math.round((base + add) * m);
      if (tier === 0 && (m > 1 || add > 0)) tier = 1;
      if (tier === 0 && p.type !== "classic") tier = 1;
      addScore(pts);
      p.flash = 1;
      Pop.text(p.x, p.y - p.r - 6, "+" + pts, { color: color, size: tier === 3 ? 30 : 22, life: 0.6, tier: tier });
      if (p.type !== "classic" || m > 1) {
        Fx.burst(p.x, p.y, { color: [color, "#ffffff"], count: tier === 3 ? 24 : 6, speed: tier === 3 ? 520 : 200, life: .45, grav: 300, size: 3 });
      }
      if (tAnim - sfxT > 0.04 || snd !== "hit") {
        sfxT = tAnim;
        Sound.clip(snd, snd === "hit" ? 0.28 : snd === "boom" ? 0.75 : 0.45, rate);
      }
    }
    function addScore(pts) {
      score = Math.max(0, score + pts);
      waveScore += pts;
      HUD.setScore(score);
      if (!goalHit && score >= target) {
        goalHit = true;
        Pop.show("perfect", { word: "Objective reached", hold: 900 });
        Overlay.vignette("#ffb830", 0.7, 700);
        Sound.clip("goal", 0.6, 1);
      }
    }

    /* A bomb: one blast per wave. Every ball inside the reach is thrown out
       of it, the pegs around shiver, the frame shakes. */
    function blast(p) {
      p.spent = true;
      for (var i = 0; i < balls.length; i++) {
        var b = balls[i], dx = b.x - p.x, dy = b.y - p.y, d = Math.sqrt(dx * dx + dy * dy);
        if (d > BLAST_REACH) continue;
        if (d < 1) { dx = 0; dy = -1; d = 1; }
        b.vx = dx / d * BLAST_SPEED; b.vy = dy / d * BLAST_SPEED;
        b.touch = {};
      }
      for (var j = 0; j < pegs.length; j++) {
        var q = pegs[j], qx = q.x - p.x, qy = q.y - p.y;
        if (qx * qx + qy * qy < BLAST_REACH * BLAST_REACH) q.flash = 1;
      }
      Fx.ring(p.x, p.y, { from: 20, to: BLAST_REACH * 1.6, color: "#ff8a3c", width: 10, life: .5 });
      Fx.ring(p.x, p.y, { from: 10, to: BLAST_REACH, color: "#ffffff", width: 4, life: .3 });
      Fx.shake(9, 0.3);
      Fx.freeze(0.05);
      Overlay.vignette("#ff8a3c", 0.55, 350);
      Pop.show("combo", { word: "Boom!", at: { x: p.x, y: p.y - 70 }, hold: 400 });
    }

    /* A ball crosses the gate band: the cell under it pays (or takes). */
    function collect(b) {
      var gi = clamp(Math.floor((b.x - BL) / BW * 5), 0, 4), g = gates[gi];
      for (var i = 0; i < 5; i++) if (b.x >= gates[i].x && b.x < gates[i].x + gates[i].w) { gi = i; g = gates[i]; }
      var v = gateValue(g);
      g.flash = 1;
      addScore(v);
      gateScore += v;
      var color = v < 0 ? "#c46bff" : g.jackpot ? "#ff4d6d" : "#ffcf5a";
      Pop.text(g.cx, GATE_TOP - 10, (v < 0 ? "" : "+") + v, { color: color, size: g.jackpot ? 32 : 24, life: 0.8, tier: g.jackpot ? 3 : 1, vy: -70 });
      Fx.burst(b.x, GATE_TOP + 10, { color: [color, "#ffffff"], count: v < 0 ? 6 : 12, speed: 260, life: .5, grav: 500, size: 3, angle: -Math.PI / 2, spread: 1.2 });
      if (g.jackpot) {
        Pop.show("bonus", { word: CONFIG.copy.jackpot, sub: "+" + v, at: { x: g.cx, y: GATE_TOP - 120 }, hold: 500 });
        Sound.clip("gate", 0.6, 1.1);
        Fx.shake(4, 0.2);
      } else if (v < 0) {
        Sound.clip("bad", 0.4, 1);
      } else {
        Sound.clip("gate", 0.35, g.val === P.gate.mid ? 1 : 0.9);
      }
      HUD.setRight(balls.length - 1 + spawnQ.length, CONFIG.copy.ballsLabel);
    }
    function burnOut(b) {
      burnt++;
      Fx.burst(b.x, b.y, { color: ["#ffffff", "#ffcf5a"], count: 10, speed: 200, life: .4, grav: 200, size: 3 });
      Sound.clip("out", 0.3, 0.8);
      HUD.setRight(balls.length - 1 + spawnQ.length, CONFIG.copy.ballsLabel);
    }

    /* --- sprites -------------------------------------------------------------- */
    function buildSprites() {
      sprites = {};
      for (var k in TYPES) sprites[k] = pegSprite(k);
      sprites.spent = pegSprite("bomb", true);
      sprites.ball = ballSprite();
    }
    function pegSprite(type, spent) {
      var T = TYPES[type], r = T.r, pad = 10, S = (r + pad) * 2;
      var c = makeCanvas(S, S), g = c.getContext("2d"), cx = S / 2, cy = S / 2;
      var color = spent ? "#6a6a78" : T.color;
      // glow halo for a special peg (pre-rendered: shadowBlur is fine here)
      if (type !== "classic" && !spent) {
        g.save(); g.shadowColor = color; g.shadowBlur = 12; g.fillStyle = rgba(color, 0.35);
        g.beginPath(); g.arc(cx, cy, r + 3, 0, Math.PI * 2); g.fill(); g.restore();
      }
      // the body
      var grd = g.createRadialGradient(cx - r * 0.35, cy - r * 0.4, r * 0.1, cx, cy, r);
      grd.addColorStop(0, "#ffffff");
      grd.addColorStop(0.25, color);
      grd.addColorStop(1, shade(color, 0.45));
      g.fillStyle = grd;
      g.beginPath(); g.arc(cx, cy, r, 0, Math.PI * 2); g.fill();
      g.lineWidth = 2; g.strokeStyle = rgba("#000000", 0.35); g.stroke();
      if (type === "bumper") {
        g.strokeStyle = "#ffe08a"; g.lineWidth = 2.5;
        g.beginPath(); g.arc(cx, cy, r - 3.5, 0, Math.PI * 2); g.stroke();
      } else if (type === "bomb") {
        g.fillStyle = spent ? "#9a9aa8" : "#ffb830";
        g.beginPath(); g.arc(cx + r * 0.35, cy - r * 0.55, 3, 0, Math.PI * 2); g.fill();
      } else if (type === "ice") {
        g.strokeStyle = "rgba(255,255,255,.85)"; g.lineWidth = 1.5;
        g.beginPath(); g.moveTo(cx - 5, cy); g.lineTo(cx + 5, cy); g.moveTo(cx, cy - 5); g.lineTo(cx, cy + 5); g.stroke();
      } else if (type === "magnet") {
        g.strokeStyle = "rgba(255,255,255,.9)"; g.lineWidth = 2;
        g.beginPath(); g.arc(cx, cy, r * 0.45, Math.PI * 0.1, Math.PI * 0.9, true); g.stroke();
      } else if (type === "fire") {
        g.fillStyle = "#fff1a8";
        g.beginPath(); g.moveTo(cx, cy - 6); g.lineTo(cx + 4, cy + 1); g.lineTo(cx, cy + 5); g.lineTo(cx - 4, cy + 1); g.closePath(); g.fill();
      }
      return c;
    }
    function ballSprite() {
      var r = BALL_R, pad = 4, S = (r + pad) * 2, c = makeCanvas(S, S), g = c.getContext("2d");
      var grd = g.createRadialGradient(S / 2 - r * 0.35, S / 2 - r * 0.4, 1, S / 2, S / 2, r);
      grd.addColorStop(0, "#ffffff"); grd.addColorStop(0.3, "#ff6b6b"); grd.addColorStop(1, "#7a0f22");
      g.fillStyle = grd; g.beginPath(); g.arc(S / 2, S / 2, r, 0, Math.PI * 2); g.fill();
      return c;
    }
    function shade(hex, k) {   // darken a #rrggbb by k
      var n = parseInt(hex.slice(1), 16), r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
      return "rgb(" + Math.round(r * (1 - k)) + "," + Math.round(g * (1 - k)) + "," + Math.round(b * (1 - k)) + ")";
    }

    /* The ground: the band's painted scene, cover-fit, a dark velvet panel
       where the board is so the pegs read, and the scrim under the HUD. The
       scene is remembered as painted or not, so a round that opened before
       the picture had decoded gets it on the next frame instead of never. */
    function sceneImage() { return ArtImages[BAND && BAND.scene] || ArtImages[Art.sceneKey()]; }
    function buildBackground() {
      if (bgCanvas) return;
      bgCanvas = makeCanvas(view.w, view.h);
      var c = bgCanvas.getContext("2d");
      var img = sceneImage();
      bgHasScene = !!(img && img.width);
      if (img && img.width) {
        var s = Math.max(view.w / img.width, view.h / img.height);
        var dw = img.width * s, dh = img.height * s;
        c.drawImage(img, (view.w - dw) / 2, (view.h - dh) / 2, dw, dh);
      } else {
        var g = c.createLinearGradient(0, 0, 0, view.h);
        g.addColorStop(0, "#4a1020"); g.addColorStop(1, "#1a050c");
        c.fillStyle = g; c.fillRect(0, 0, view.w, view.h);
      }
      var band = Layout.top + 60;
      var tg = c.createLinearGradient(0, 0, 0, band);
      tg.addColorStop(0, "rgba(0,0,0,0.6)"); tg.addColorStop(1, "rgba(0,0,0,0)");
      c.fillStyle = tg; c.fillRect(0, 0, view.w, band);
      // the board panel
      roundRect(c, BL - 6, BOARD_TOP - 8, BW + 12, GATE_BOTTOM - BOARD_TOP + 16, 22);
      c.fillStyle = "rgba(24,2,10,0.62)"; c.fill();
      c.lineWidth = 3; c.strokeStyle = "rgba(255,184,48,0.55)"; c.stroke();
      // the chute line the balls fall from
      c.strokeStyle = "rgba(255,184,48,0.25)"; c.lineWidth = 2;
      c.setLineDash([8, 10]);
      c.beginPath(); c.moveTo(BL + 10, BOARD_TOP + 22); c.lineTo(BR - 10, BOARD_TOP + 22); c.stroke();
      c.setLineDash([]);
    }

    /* --- render ----------------------------------------------------------------- */
    function render() {
      if (!bgHasScene) { var img = sceneImage(); if (img && img.width) { bgCanvas = null; buildBackground(); } }
      ctx.drawImage(bgCanvas, 0, 0, view.w, view.h);
      drawGauge();
      drawGates();
      drawPegs();
      drawBalls();
      drawDeck();
      if (state === "aim") drawAim();
    }

    /* The objective, on the board itself: a fill rising from the gates toward
       the top as the score climbs, with the three stars' lines across it. The
       top of the board is the third star — 2.2x the objective — and the first
       star sits at 45% of it, so a level's whole ladder is on the wall. */
    function drawGauge() {
      var top = BOARD_TOP + 34, h = GATE_TOP - 4 - top, full = target * 2.2;
      var f = clamp(score / full, 0, 1), fh = h * f;
      ctx.save();
      roundRect(ctx, BL, top, BW, h, 12); ctx.clip();
      var g = ctx.createLinearGradient(0, GATE_TOP - fh, 0, GATE_TOP);
      g.addColorStop(0, goalHit ? "rgba(255,184,48,0.20)" : "rgba(255,120,80,0.13)");
      g.addColorStop(1, goalHit ? "rgba(255,184,48,0.05)" : "rgba(255,120,80,0.03)");
      ctx.fillStyle = g; ctx.fillRect(BL, GATE_TOP - 4 - fh, BW, fh);
      ctx.fillStyle = goalHit ? "rgba(255,230,150,0.7)" : "rgba(255,170,120,0.5)";
      ctx.fillRect(BL, GATE_TOP - 4 - fh - 2, BW, 3);
      var marks = [1 / 2.2, 1.5 / 2.2, 1], labels = [target, Math.round(target * 1.5), Math.round(full)];
      ctx.font = font(15, 800); ctx.textAlign = "right"; ctx.textBaseline = "bottom";
      for (var i = 0; i < 3; i++) {
        var y = GATE_TOP - 4 - h * marks[i], on = f >= marks[i] - 0.0001;
        ctx.strokeStyle = on ? "rgba(255,220,120,0.7)" : "rgba(255,255,255,0.16)"; ctx.lineWidth = 1.5;
        ctx.setLineDash([6, 8]);
        ctx.beginPath(); ctx.moveTo(BL + 8, y); ctx.lineTo(BR - 8, y); ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = on ? "rgba(255,220,120,0.9)" : "rgba(255,255,255,0.3)";
        ctx.fillText(labels[i], BR - 12, y - 2);
      }
      ctx.restore();
    }

    function drawGates() {
      ctx.save();
      for (var i = 0; i < 5; i++) {
        var g = gates[i], v = gateValue(g), x = g.x, w = g.w, y = GATE_TOP;
        var color = v < 0 ? "#c46bff" : g.jackpot ? "#ff4d6d" : boost.gold ? "#ffe08a" : "#ffcf5a";
        // the cell
        roundRect(ctx, x + 3, y, w - 6, GATE_H, 10);
        ctx.fillStyle = v < 0 ? "rgba(90,30,140,0.45)" : g.jackpot ? "rgba(255,77,109,0.22)" : "rgba(255,184,48,0.12)";
        ctx.fill();
        if (g.flash > 0) { ctx.fillStyle = rgba(color, 0.55 * g.flash); ctx.fill(); }
        ctx.lineWidth = 2; ctx.strokeStyle = rgba(color, 0.7); ctx.stroke();
        // the value
        ctx.font = font(g.jackpot ? 30 : 24, 900); ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillStyle = color;
        ctx.fillText((v < 0 ? "" : "+") + v, g.cx, y + GATE_H / 2 + (g.flash > 0 ? -3 * g.flash : 0));
        // a gold pin at the seam
        if (i > 0) {
          ctx.fillStyle = "#ffcf5a";
          ctx.beginPath(); ctx.arc(x, y - 6, 6, 0, Math.PI * 2); ctx.fill();
          ctx.fillStyle = "rgba(255,255,255,0.7)";
          ctx.beginPath(); ctx.arc(x - 1.5, y - 8, 2, 0, Math.PI * 2); ctx.fill();
        }
      }
      ctx.restore();
    }

    function drawPegs() {
      for (var i = 0; i < pegs.length; i++) {
        var p = pegs[i], sp = p.type === "bomb" && p.spent ? sprites.spent : sprites[p.type];
        var S = sp.width / view.dpr, k = 1 + p.flash * 0.35;
        if (p.type === "fire" || p.type === "magnet") k *= 1 + 0.05 * Math.sin(tAnim * 8 + p.id);
        ctx.drawImage(sp, p.x - S / 2 * k, p.y - S / 2 * k, S * k, S * k);
        if (p.flash > 0.02) {
          ctx.strokeStyle = rgba("#ffffff", p.flash * 0.9); ctx.lineWidth = 3;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.r + 4 + (1 - p.flash) * 14, 0, Math.PI * 2); ctx.stroke();
        }
      }
    }

    function drawBalls() {
      var img = ArtImages["ball0" + clamp(wave, 1, 5)];
      for (var i = 0; i < balls.length; i++) {
        var b = balls[i];
        if (b.burn > 0 || b.frozen > 0 || b.charged > 0) {
          var c = b.burn > 0 ? "#ff7a1a" : b.frozen > 0 ? "#5ad8ff" : "#c46bff";
          ctx.fillStyle = rgba(c, 0.28 + 0.12 * Math.sin(tAnim * 14 + b.id));
          ctx.beginPath(); ctx.arc(b.x, b.y, BALL_R + 8, 0, Math.PI * 2); ctx.fill();
          ctx.strokeStyle = rgba(c, 0.9); ctx.lineWidth = 2.5;
          ctx.beginPath(); ctx.arc(b.x, b.y, BALL_R + 3, 0, Math.PI * 2); ctx.stroke();
          // a burning ball leaves embers
          if (b.burn > 0) {
            b.trail += 1;
            if (b.trail % 3 === 0) Fx.burst(b.x, b.y, { color: ["#ff7a1a", "#ffd166"], count: 1, speed: 40, life: .35, grav: -120, size: 3 });
          }
        }
        if (img && img.width) {
          var s = (BALL_R + 3) * 2;
          ctx.drawImage(img, b.x - s / 2, b.y - s / 2, s, s);
        } else {
          var S = sprites.ball.width / view.dpr;
          ctx.drawImage(sprites.ball, b.x - S / 2, b.y - S / 2, S, S);
        }
      }
    }

    /* The deck: five cards under the HUD. Live and breathing while a card is
       to be picked, plain while the wave falls, dimmed once played. */
    function drawDeck() {
      var choose = state === "choose" && !ended;
      var shake = deckShake > 0 ? Math.sin(deckShake * 60) * 6 * deckShake : 0;
      for (var i = 0; i < 5; i++) {
        var card = deck[i], def = CARDS[card.key];
        var x = cardX(i) + shake, y = DECK_Y, k = 1 + card.pop * 0.18;
        if (choose) y -= 4 + 3 * Math.sin(tAnim * 3 + i * 0.9);
        ctx.save();
        ctx.translate(x + CARD_W / 2, y + CARD_H / 2); ctx.scale(k, k); ctx.translate(-CARD_W / 2, -CARD_H / 2);
        if (card.used) ctx.globalAlpha = 0.32;
        roundRect(ctx, 0, 0, CARD_W, CARD_H, 14);
        var g = ctx.createLinearGradient(0, 0, 0, CARD_H);
        g.addColorStop(0, card.used ? "#3a3038" : "#5a1020"); g.addColorStop(1, card.used ? "#1e1a20" : "#2a0612");
        ctx.fillStyle = g; ctx.fill();
        ctx.lineWidth = 3;
        ctx.strokeStyle = card.used ? "rgba(255,255,255,0.25)" : choose ? rgba(def.color, 0.75 + 0.25 * Math.sin(tAnim * 5 + i)) : "rgba(255,184,48,0.6)";
        ctx.stroke();
        // the pictogram
        var img = ArtImages[def.icon];
        if (img && img.width) {
          var s = 72, ar = img.width / img.height, w = ar >= 1 ? s : s * ar, h = ar >= 1 ? s / ar : s;
          ctx.drawImage(img, CARD_W / 2 - w / 2, 48 - h / 2, w, h);
        } else {
          ctx.fillStyle = def.color;
          ctx.beginPath(); ctx.arc(CARD_W / 2, 48, 28, 0, Math.PI * 2); ctx.fill();
        }
        // the count, when the card turns pegs
        if (def.n) {
          ctx.font = font(15, 900); ctx.textAlign = "right"; ctx.textBaseline = "top";
          ctx.fillStyle = "rgba(255,255,255,0.85)";
          ctx.fillText("x" + def.n, CARD_W - 9, 7);
        }
        // the name
        ctx.font = font(17, 900); ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillStyle = card.used ? "#c9c2cc" : "#ffe6a8";
        ctx.fillText(upper(Lang.t(def.name)), CARD_W / 2, CARD_H - 24);
        if (card.used) {
          ctx.globalAlpha = 0.85;
          ctx.strokeStyle = "rgba(255,255,255,0.55)"; ctx.lineWidth = 4;
          ctx.beginPath(); ctx.moveTo(18, 18); ctx.lineTo(CARD_W - 18, CARD_H - 18); ctx.stroke();
        }
        ctx.restore();
      }
    }

    /* Where the wave will fall from: a marker under the finger, on the chute. */
    function drawAim() {
      var y = BOARD_TOP + 8, pulse = 0.6 + 0.4 * Math.sin(tAnim * 6);
      ctx.fillStyle = rgba("#ffb830", pulse);
      ctx.beginPath(); ctx.moveTo(tapX - 16, y - 18); ctx.lineTo(tapX + 16, y - 18); ctx.lineTo(tapX, y + 8); ctx.closePath(); ctx.fill();
      ctx.strokeStyle = rgba("#ffb830", 0.35 * pulse); ctx.lineWidth = 3;
      ctx.setLineDash([6, 12]);
      ctx.beginPath(); ctx.moveTo(tapX, y + 14); ctx.lineTo(tapX, y + 120); ctx.stroke();
      ctx.setLineDash([]);
    }

    /* --- the end ------------------------------------------------------------------ */
    function onTimeUp() { endRun(CONFIG.copy.timeUp); }
    function endRun(title) {
      if (ended) return;
      ended = true;
      balls = []; spawnQ = [];
      var best = Math.max(score, Store.get("bestScore", 0));
      var stars = score >= target * 2.2 ? 3 : score >= target * 1.5 ? 2 : score >= target ? 1 : 0;
      endRound({
        title: stars === 3 ? CONFIG.copy.jackpot : title,
        variant: stars === 3 ? "win" : "",
        score: score,
        stars: stars,
        rows: [
          { label: "Peg hits",   value: hits },
          { label: "Gate bonus", value: gateScore, grade: "accent" },
          { label: "Best wave",  value: bestWave },
          { label: "Best score", value: best, grade: "gold" }
        ],
        track: { score: score, hits: hits, gates: gateScore, waves: wave }
      });
    }

    /* The web target's level layer: `applyLevel` hands the climb's `d` before
       the round (the objective on the wall comes from it), and `levelWon` ends
       the round through the game's own result on the third star, so the end
       screen keeps these stat rows. Ignored by the playable. */
    return { reset: reset, onDown: onDown, onMove: onMove, update: update, render: render,
             onTimeUp: onTimeUp, onResize: onResize, applyLevel: applyLevel, levelWon: endRun };
  })();

